import{_ as t,o as r,c as o,a5 as i}from"./chunks/framework.DJo0M80U.js";const _=JSON.parse('{"title":"保证 redirect 参数的安全性 重定向","description":"保证 redirect 参数的安全性 ，防止出现「开放重定向漏洞」⚠️。 背景问题 在守卫里，我们常常写： router.push(to.query.redirect DEFAULT ROUTE PATH) 如果没有限制，攻击者就可以构造链接： https://your site。","frontmatter":{"title":"保证 redirect 参数的安全性 重定向","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","路由与状态管理"],"description":"保证 redirect 参数的安全性 ，防止出现「开放重定向漏洞」⚠️。 背景问题 在守卫里，我们常常写： router.push(to.query.redirect DEFAULT ROUTE PATH) 如果没有限制，攻击者就可以构造链接： https://your site。","sidebarWeight":29,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/vueRouter/保证 redirect 参数的安全性 重定向.md"},"headers":[],"relativePath":"posts/Vue系统教程/04-路由与状态管理/保证 redirect 参数的安全性 重定向.md","filePath":"posts/Vue系统教程/04-路由与状态管理/保证 redirect 参数的安全性 重定向.md"}'),d={name:"posts/Vue系统教程/04-路由与状态管理/保证 redirect 参数的安全性 重定向.md"};function c(s,e,a,l,n,u){return r(),o("div",null,[...e[0]||(e[0]=[i('<div><h1 id="保证-redirect-参数的安全性-重定向" tabindex="-1">保证 redirect 参数的安全性 重定向 <a class="header-anchor" href="#保证-redirect-参数的安全性-重定向" aria-label="Permalink to &quot;保证 redirect 参数的安全性 重定向&quot;">​</a></h1><blockquote><p>本节目标：理解“保证 redirect 参数的安全性 重定向”的核心思路，并能把它用于实际开发或面试表达。 <strong><strong>保证 redirect 参数的安全性</strong></strong>，防止出现「开放重定向漏洞」⚠️。</p></blockquote><h3 id="背景问题" tabindex="-1">背景问题 <a class="header-anchor" href="#背景问题" aria-label="Permalink to &quot;背景问题&quot;">​</a></h3><p>在守卫里，我们常常写： router.push(to.query.redirect || DEFAULT_ROUTE_PATH)</p><p>如果没有限制，攻击者就可以构造链接： <a href="https://your-site.com/user?redirect=https://evil.com" target="_blank" rel="noreferrer">https://your-site.com/user?redirect=https://evil.com</a></p><p>用户登录后就会被直接跳到 <code>evil.com</code>，这就是典型的 <strong><strong>开放重定向漏洞</strong></strong>。</p><h3 id="getsaferedirect-的作用" tabindex="-1">** <strong><code>getSafeRedirect</code></strong> **的作用 <a class="header-anchor" href="#getsaferedirect-的作用" aria-label="Permalink to &quot;** **`getSafeRedirect`** **的作用&quot;">​</a></h3><ol><li><strong><strong>解码并校验</strong></strong><ul><li>尝试 <code>decodeURIComponent</code>，避免双重编码绕过。</li></ul></li><li><strong><strong>必须是站内相对路径</strong></strong><ul><li>要求 redirect 必须以 <code>/</code> 开头。</li><li>排除外链（<code>http://</code>、<code>https://</code>、<code>//</code> 开头的路径）。</li></ul></li><li><strong><strong>兜底逻辑</strong></strong><ul><li>如果 redirect 不合法 → 返回 <code>undefined</code>，守卫会回退到首页。</li></ul></li></ol><h3 id="简化理解" tabindex="-1">简化理解 <a class="header-anchor" href="#简化理解" aria-label="Permalink to &quot;简化理解&quot;">​</a></h3><ul><li>✅ <code>?redirect=/dashboard/workplace</code> → 安全，允许。</li><li>❌ <code>?redirect=https://evil.com</code> → 被拦截，不跳转。</li><li>❌ <code>?redirect=//evil.com</code> → 被拦截，不跳转。</li><li>❌ <code>?redirect=javascript:alert(1)</code> → 因为不以 <code>/</code> 开头，直接拒绝。</li></ul><p>👉 也就是说，<code>getSafeRedirect</code> 的存在是为了<strong><strong>只允许跳转到你自己系统里的页面</strong></strong>，避免用户被利用跳去第三方恶意网站。</p></div>',1)])])}const h=t(d,[["render",c]]);export{_ as __pageData,h as default};
